// envVarSubstitutionHookFunc replaces a complete ${VAR} reference when VAR is set.
func envVarSubstitutionHookFunc() mapstructure.DecodeHookFunc {
	return func(from reflect.Kind, to reflect.Kind, data interface{}) (interface{}, error) {
		if from != reflect.String {
			return data, nil
		}

		value := data.(string)
		if !envVarReference.MatchString(value) {
			return data, nil
		}

		if replacement, ok := os.LookupEnv(value[2 : len(value)-1]); ok {
			return replacement, nil
		}

		return data, nil
	}
}

